(()=>{
const key=document.body.dataset.category,c=DF_CATEGORIES[key];
if(!c)return;
const base='https://dongfeng-evtruck.com/';
const seo={
 tractor:{title:'Dongfeng Electric Tractor Trucks | TE Series 4x2 & 6x4 EV Tractors',description:'Explore Dongfeng TE electric tractor truck configurations for port, regional and heavy-haul operations, including 42-120 t GCW, CATL batteries and charging options.',url:'electric-tractor.html',image:'assets/catalog/tractor-heavy.jpg'},
 cargo:{title:'Dongfeng Electric Cargo Trucks | KT & KTH Commercial EV Chassis',description:'Review Dongfeng KT and KTH electric cargo truck models for urban and regional logistics, including 18-31 t GVW platforms, CATL battery options and body applications.',url:'electric-cargo.html',image:'assets/catalog/cargo-kt5.jpg'},
 dump:{title:'Dongfeng Electric Dump Trucks | KTA & TZ Mining Construction EVs',description:'Compare Dongfeng KTA and TZ electric dump truck configurations for construction, quarry and mining duty cycles, including 31-80 t GVW and right-hand-drive options.',url:'electric-dump.html',image:'assets/catalog/dump-standard.jpg'},
 special:{title:'Dongfeng Electric Special Trucks | Sanitation, Mixer & Municipal EVs',description:'Explore Dongfeng electric special vehicle chassis for sprinklers, sweepers, refuse trucks and concrete mixers across 4x2, 6x4 and 8x4 configurations.',url:'electric-special.html',image:'assets/catalog/special-range.jpg'}
}[key];
const setMeta=(selector,attr,value)=>{let el=document.head.querySelector(selector);if(!el){el=document.createElement('meta');if(selector.includes('property=')){el.setAttribute('property',selector.match(/property="([^"]+)"/)?.[1]||'')}else{el.setAttribute('name',selector.match(/name="([^"]+)"/)?.[1]||'')}document.head.appendChild(el)}el.setAttribute(attr,value)};
const setLink=(rel,href)=>{let el=document.head.querySelector(`link[rel="${rel}"]`);if(!el){el=document.createElement('link');el.rel=rel;document.head.appendChild(el)}el.href=href};
if(seo){const url=base+seo.url;document.title=seo.title;document.querySelector('meta[name="description"]')?.setAttribute('content',seo.description);setLink('canonical',url);setMeta('meta[property="og:title"]','content',seo.title);setMeta('meta[property="og:description"]','content',seo.description);setMeta('meta[property="og:url"]','content',url);setMeta('meta[property="og:image"]','content',base+seo.image);setMeta('meta[property="og:type"]','content','website');setMeta('meta[name="twitter:card"]','content','summary_large_image');const schema=document.createElement('script');schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'CollectionPage',name:c.title,url,description:seo.description,mainEntity:{'@type':'ItemList',itemListElement:c.models.map((m,i)=>({'@type':'ListItem',position:i+1,name:m[0],description:`${m[1]} ${m[2]} electric truck configuration`}))}});document.head.appendChild(schema)}
document.querySelector('[data-title]').textContent=c.title;
document.querySelector('[data-kicker]').textContent=c.kicker;
document.querySelector('[data-intro]').textContent=c.intro;
document.querySelector('[data-hero]').src=c.hero;
const labels=['Model / Application','Drive','GVW / GCW','CATL Battery','Motor rated / peak','Gearbox','Wheelbase','Front / rear axle','Tyres','Safety','Charging / notes'];
document.querySelector('[data-models]').innerHTML=c.models.map((m,i)=>`<article class="spec-card"><div class="spec-no">${String(i+1).padStart(2,'0')}</div><div><p class="eyebrow">${m[1]} · ${m[2]}</p><h2>${m[0]}</h2></div><dl>${m.slice(3).map((v,j)=>`<div><dt>${labels[j+3]}</dt><dd>${v}</dd></div>`).join('')}</dl><a class="button outline" href="contact.html?model=${encodeURIComponent(m[0])}">Request this configuration</a></article>`).join('');
})();